window.CA = {"date": "Wednesday, 15 July 2026", "updated": "2026-07-15 14:39", "updated_label": "15 Jul 2026, 14:39 IST", "items": [{"title": "India-UK Comprehensive Economic and Trade Agreement (CETA) Enters into Force", "category": "ir", "category_name": "International Relations", "summary": "The India-UK Free Trade Agreement, officially termed the Comprehensive Economic and Trade Agreement (CETA), came into force on July 15, 2026. Under the deal, nearly 99% of Indian exports gain duty-free access to the UK market, covering textiles, leather goods, footwear, and engineering products. The UK will see reduced tariffs on Scotch whisky, automobiles, and luxury goods entering India. The first consignments valued at USD 4,46,046 were flagged off from Chennai, and the UK Trade Minister described it as the 'fastest implementation' of any trade deal.", "exam_angle": "This is a landmark bilateral trade agreement with direct implications for India's exports, FDI, and services sector. Aspirants must know the key sectors benefited, the investment-pact component, and the broader India-UK strategic relationship.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Agreement: India-UK Comprehensive Economic and Trade Agreement (CETA)", "Effective date: July 15, 2026", "Nearly 99% of Indian exports to get duty-free access to UK", "First consignment flagged off from Chennai worth USD 4,46,046"], "source": "PIB / NDTV / The Hindu", "day": "2026-07-15", "day_label": "15 Jul"}, {"title": "131st Constitutional Amendment Bill (Delimitation): Political Manoeuvring Ahead of Parliament", "category": "polity", "category_name": "Polity & Governance", "summary": "The 131st Constitutional Amendment Bill on delimitation has become a major political flashpoint, with the BJP reportedly wooing NCP (SP) and DMK for support. NCP (SP) leader Supriya Sule stated her party would back the delimitation bill with certain riders but ruled out joining the NDA. Senior Congress leader P. Chidambaram alleged the BJP is wooing regional parties to secure the two-thirds majority needed for a constitutional amendment. The bill seeks to redraw parliamentary and assembly constituencies based on the 2021 census data.", "exam_angle": "Delimitation is governed by Articles 82 and 170 of the Constitution; a constitutional amendment bill requires a special majority under Article 368. This item connects to federalism, representation, and scheduled constitutional bodies like the Delimitation Commission.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Bill: 131st Constitutional Amendment Bill (Delimitation)", "Requires special majority under Article 368 of the Constitution", "Key parties being wooed: NCP (SP), DMK", "Delimitation governed by Articles 82 (Lok Sabha) and 170 (State Assemblies)"], "source": "Deccan Herald / The Indian Express", "day": "2026-07-15", "day_label": "15 Jul"}, {"title": "US Senate Bill Proposes 100% Tariff on Countries Buying Russian Oil; India Faces Risk", "category": "ir", "category_name": "International Relations", "summary": "US Senators unveiled a bill proposing 100% secondary tariffs on India, China, and three other countries that continue purchasing Russian crude oil, revised downward from an earlier threatened 500% tariff. President Trump backed the legislation as part of broader sanctions pressure on Russia amid the ongoing Ukraine conflict. India, which has been the largest buyer of discounted Russian oil since 2022, faces significant economic risk if the bill is enacted. The development adds fresh uncertainty to India's energy security and import diversification strategy.", "exam_angle": "This directly impacts India's energy security, crude oil import policy, and India-US relations. It also connects to the broader debate on secondary sanctions, CAATSA, and India's strategic autonomy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Proposed tariff: 100% on countries buying Russian oil (revised from 500%)", "Countries targeted: India, China, and three others", "India has been Russia's largest oil buyer post-2022 Ukraine war", "Bill backed by US President Trump as part of Russia sanctions package"], "source": "NDTV / The Times of India", "day": "2026-07-15", "day_label": "15 Jul"}, {"title": "Indian Sailor Killed in Strait of Hormuz Attack; India Summons Iranian Ambassador", "category": "ir", "category_name": "International Relations", "summary": "An Indian seafarer was killed when his vessel was struck during US-Iran hostilities in the Strait of Hormuz, making it one of the first Indian casualties in the conflict. India's Ministry of External Affairs summoned the Iranian Ambassador to lodge a strong protest, condemning attacks on vessels carrying Indian crew. The Indian government also announced it would account for every Indian seafarer irrespective of the flag of the vessel. The Strait of Hormuz handles approximately 20% of global oil trade and its closure threatens global energy supplies.", "exam_angle": "The Strait of Hormuz is a critical chokepoint for global oil trade; India's response—summoning an envoy—is an important diplomatic tool. This connects to GS Paper 2 (IR) themes of diaspora welfare, maritime security, and India's West Asia policy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["An Indian sailor was killed in a strike on a vessel in the Strait of Hormuz", "India summoned the Iranian Ambassador in protest", "Government pledged to track all Indian seafarers regardless of vessel flag", "Strait of Hormuz handles ~20% of global oil trade"], "source": "The Indian Express / Hindustan Times", "day": "2026-07-15", "day_label": "15 Jul"}, {"title": "US-Iran Military Conflict: Hormuz Blockade Reimposed, Strikes on Iranian Facilities", "category": "ir", "category_name": "International Relations", "summary": "The United States reimposed a naval blockade on Iran and launched fresh strikes on Iranian military facilities, including what reports described as an Iranian Army base, killing at least seven. Iran's Islamic Revolutionary Guard Corps (IRGC) claimed counter-strikes on US military sites in the Gulf. Iran threatened to block additional vital seaways and declared Hormuz would remain closed until the US ceased its military operations. Trump warned of further strikes on Iranian power plants and bridges if no deal was reached.", "exam_angle": "The US-Iran conflict and Hormuz closure directly affects India's oil imports, diaspora safety, and regional stability in West Asia—a recurring theme in GS Paper 2 (IR) and GS Paper 3 (Energy Security).", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["US reimposed Hormuz naval blockade against Iran", "US strikes reportedly killed at least 7 at Iranian Army base", "IRGC claimed counter-strikes on US military sites in the Gulf", "Iran threatened to block additional seaways"], "source": "Reuters / The Hindu / Al Jazeera", "day": "2026-07-15", "day_label": "15 Jul"}, {"title": "Iran Used Mobile Data Roaming and Ad-Tech to Track US Military Personnel in Gulf", "category": "defence", "category_name": "Defence & Security", "summary": "A Financial Times investigation revealed that Iran used commercial mobile data roaming networks and advertising technology (ad-tech) to covertly track the movements of US military personnel across the Middle East. The technique involved exploiting data from mobile networks and digital advertising ecosystems to triangulate locations of servicemen. This represents a significant non-kinetic intelligence and cyber-surveillance capability used in an active conflict zone. The revelation has raised alarms about the vulnerability of commercial digital infrastructure to state-level exploitation.", "exam_angle": "This is relevant to GS Paper 3 (Internal Security/Cyber Security) themes of cyber warfare, information warfare, and the dual-use nature of commercial technology in modern conflicts.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Iran exploited mobile data roaming and ad-tech platforms to track US troops", "Technique used commercial digital infrastructure for state-level surveillance", "Reported by the Financial Times", "Highlights vulnerability of commercial networks to military intelligence exploitation"], "source": "NDTV / Moneycontrol", "day": "2026-07-15", "day_label": "15 Jul"}, {"title": "PM Modi Claimed to Have Helped Prevent Russia's Tactical Nuclear Strike on Ukraine in 2022: Polish Minister", "category": "ir", "category_name": "International Relations", "summary": "A Polish minister claimed that Indian Prime Minister Narendra Modi played a role in dissuading Russian President Vladimir Putin from launching a tactical nuclear strike on Ukraine in 2022. The claim, reported by The Times of India, suggests back-channel diplomatic engagement by India during a critical phase of the Russia-Ukraine war. India had publicly stated in September 2022 that 'this is not an era of war' during Modi's meeting with Putin in Samarkand. India's strategic autonomy and its unique position as a mediator between Russia and the West are highlighted by this claim.", "exam_angle": "India's strategic autonomy, its relationship with Russia, and its role as a peace mediator are key IR themes. The Samarkand statement connects to PM Modi's diplomacy and India's stated opposition to nuclear use.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Claim made by a Polish minister regarding 2022 Russia-Ukraine war", "Modi reportedly persuaded Putin against using tactical nuclear weapons", "Modi's Samarkand statement (Sept 2022): 'This is not an era of war'", "Highlights India's strategic autonomy and mediatory role"], "source": "The Times of India", "day": "2026-07-15", "day_label": "15 Jul"}, {"title": "Air India Crash Probe: AAIB Tells Supreme Court Draft Report Due by October 2026", "category": "polity", "category_name": "Polity & Governance", "summary": "The Aircraft Accident Investigation Bureau (AAIB) informed the Supreme Court of India that the draft final report on the June 2025 Air India crash will be ready by October 2026. The AAIB also told the court that cockpit voice recordings cannot be shared publicly during the ongoing investigation. The Supreme Court is monitoring the probe after concerns were raised that a 'pilot-blame narrative' was potentially influencing witnesses. The crash, which occurred in June 2025, is one of India's deadliest aviation disasters.", "exam_angle": "This connects to the role of statutory investigation bodies (AAIB under the Aircraft Act), the Supreme Court's suo motu jurisdiction, and the importance of impartial accident investigations in civil aviation governance.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Investigating body: Aircraft Accident Investigation Bureau (AAIB)", "Draft final report expected: October 2026", "Cockpit voice recordings ruled non-shareable during investigation", "Supreme Court monitoring probe amid concerns over witness influence"], "source": "The Hindu / Deccan Herald / NDTV", "day": "2026-07-15", "day_label": "15 Jul"}, {"title": "Supreme Court Questions Whether English Can Be Considered an Indigenous Indian Language", "category": "polity", "category_name": "Polity & Governance", "summary": "The Supreme Court of India raised an intriguing constitutional and socio-linguistic question, asking whether English can be considered an indigenous Indian language given its deep entrenchment in public life, judiciary, and administration over centuries. The observation was made during proceedings likely related to a language-policy or medium-of-instruction case. The remark has significant implications for debates around the three-language formula, the Official Languages Act, and the constitutional status of English under the Eighth Schedule. English is not listed in the Eighth Schedule but continues as an associate official language under Article 343.", "exam_angle": "Constitutional provisions on language policy (Articles 343–351), the Eighth Schedule, and debates around linguistic identity and the three-language formula are directly relevant for GS Paper 2.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Supreme Court questioned if English qualifies as an indigenous Indian language", "English is NOT listed in the Eighth Schedule of the Constitution", "English continues as associate official language under Article 343(2)", "Eighth Schedule currently lists 22 scheduled languages"], "source": "The Hindu", "day": "2026-07-15", "day_label": "15 Jul"}, {"title": "India Bans Import of Goods Manufactured Using Forced Labour", "category": "economy", "category_name": "Economy & Banking", "summary": "India has announced a ban on the import of goods manufactured using forced labour, even as a US investigation into the matter remains pending. The move aligns India with global trade norms around ethical supply chains and may be partly aimed at preempting US trade scrutiny. The ban was announced by the Ministry of Commerce and connects to provisions under WTO agreements on trade and human rights. The policy is significant in the context of India's positioning as an alternative manufacturing hub and its sensitivity around supply chain due diligence.", "exam_angle": "This policy connects to GS Paper 3 themes of trade policy, ethical supply chains, and India's WTO obligations. It also reflects India's proactive trade diplomacy especially in the context of US scrutiny.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["India bans imports of goods made using forced labour", "Announced by the Ministry of Commerce", "Move aligns with US and EU ethical trade requirements", "Relevant to WTO rules on trade and labour standards"], "source": "The Hindu / The Indian Express", "day": "2026-07-15", "day_label": "15 Jul"}, {"title": "National Health Research Policy 2026 Released: India to Overhaul Public Health Research System", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "The Indian government released the National Health Research Policy 2026, aimed at overhauling the country's health research system to better align it with public health priorities. The policy seeks to strengthen translational research, bridge gaps between laboratory findings and clinical applications, and increase domestic funding for health R&D. It envisages greater coordination between the Indian Council of Medical Research (ICMR), academic institutions, and industry. The policy is being seen as a strategic response to lessons from the COVID-19 pandemic.", "exam_angle": "National health policies and ICMR's role are frequently tested in GS Paper 2 (Health/Governance). The policy's emphasis on translational research and public health linkages is a key exam takeaway.", "gs_paper": "GS Paper 2 (Governance)", "key_facts": ["Policy: National Health Research Policy 2026", "Released by the Ministry of Health and Family Welfare", "Key body: Indian Council of Medical Research (ICMR)", "Focus: Translational research, public health alignment, post-COVID lessons"], "source": "NDTV", "day": "2026-07-15", "day_label": "15 Jul"}, {"title": "IDBI Bank Stake Sale Process Revived; Government Keen to Expedite Disinvestment", "category": "economy", "category_name": "Economy & Banking", "summary": "The Union government has signalled renewed intent to proceed with the strategic disinvestment of IDBI Bank, with reports indicating the process has been placed back on the priority list. The government and Life Insurance Corporation (LIC) together hold a majority stake in IDBI Bank, and the disinvestment has been pending since 2021 when it was first announced. The Reserve Bank of India's 'fit and proper' criteria for the new owner remain a key hurdle. The move is part of the government's broader disinvestment and asset monetisation strategy.", "exam_angle": "IDBI Bank disinvestment is a longstanding topic in GS Paper 3 (Economy) covering privatisation, PSU reforms, and the role of LIC as a state investor. Aspirants must know the shareholding structure and regulatory hurdles.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Government + LIC together hold majority stake in IDBI Bank", "Disinvestment first announced in Union Budget 2021-22", "RBI 'fit and proper' criteria for buyer remains a key regulatory hurdle", "Part of the government's National Monetisation Pipeline/disinvestment agenda"], "source": "The Times of India", "day": "2026-07-15", "day_label": "15 Jul"}, {"title": "FBI Adds Indian Gangster Nitish Kaushal alias 'Lala' to Most Wanted List", "category": "persons", "category_name": "Persons & Awards in News", "summary": "The US Federal Bureau of Investigation (FBI) added Indian gangster Nitish Kaushal, alias 'Lala', to its Most Wanted list. Kaushal is reportedly a key associate of Jaggu Bhagwanpuria, who is himself linked to the Lawrence Bishnoi gang. The network is accused of extortion, murder, and transnational organised crime. India's Ministry of External Affairs reaffirmed India's commitment to combating terrorism and organised crime in the context of these arrests and listings.", "exam_angle": "Transnational organised crime, extradition mechanisms, and India-US law enforcement cooperation are relevant GS Paper 3 (Internal Security) topics. The Bishnoi gang's international reach is a frequently appearing current affairs theme.", "gs_paper": "GS Paper 3 (Internal Security)", "key_facts": ["Nitish Kaushal alias 'Lala' added to FBI Most Wanted list", "Associate of Jaggu Bhagwanpuria, linked to Lawrence Bishnoi gang", "Network accused of extortion, murder, transnational crime", "MEA reaffirmed India's commitment to fighting terror and organised crime"], "source": "The Hindu / The Indian Express", "day": "2026-07-15", "day_label": "15 Jul"}, {"title": "India Blames Pakistan for Protests in Pakistan-Occupied Kashmir (PoK)", "category": "ir", "category_name": "International Relations", "summary": "India formally accused Pakistan of instigating and organising protests in Pakistan-Occupied Kashmir (PoK) and demanded accountability from Islamabad. The Indian government stated that the unrest in PoK reflects the Pakistani state's use of local grievances for strategic purposes. This comes amid continuing tensions over cross-border terrorism and the status of Jammu & Kashmir following the revocation of Article 370 in 2019. India has consistently maintained that PoK is an integral part of India illegally occupied by Pakistan.", "exam_angle": "PoK, Article 370, India-Pakistan relations, and the Line of Control (LoC) are perennial GS Paper 2 (IR) topics. India's diplomatic positioning on PoK protests is exam-relevant.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India accused Pakistan of fomenting protests in PoK", "India maintains PoK is an integral part of India under illegal occupation", "Connects to Article 370 abrogation (August 2019) and Jammu & Kashmir reorganisation", "Pakistan-occupied territories include PoK and Gilgit-Baltistan"], "source": "The Hindu", "day": "2026-07-15", "day_label": "15 Jul"}, {"title": "Jaishankar Attends India-EU Summit in Brussels; Meets European Council President", "category": "ir", "category_name": "International Relations", "summary": "External Affairs Minister S. Jaishankar attended the India-EU Summit in Brussels and met the President of the European Council, signalling advancement in India-EU strategic ties. The discussions covered trade and technology cooperation, the stalled India-EU FTA negotiations, and geopolitical coordination. Jaishankar described the India-EU relationship as having 'advanced significantly' post-summit. The India-EU Summit is a key platform for reviewing the Strategic Partnership established in 2004.", "exam_angle": "India-EU relations, the Strategic Partnership of 2004, and the India-EU FTA (Broad-based Trade and Investment Agreement—BTIA) negotiations are important IR topics for the exam.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["EAM Jaishankar attended India-EU Summit in Brussels", "Met European Council President to discuss trade and technology", "India-EU Strategic Partnership established in 2004", "India-EU BTIA (FTA) negotiations have been ongoing since 2007"], "source": "India Today / The Hindu", "day": "2026-07-15", "day_label": "15 Jul"}, {"title": "QS Asia University Rankings 2026: India's Position Among Top 10 Asian Universities", "category": "reports", "category_name": "Reports & Indices", "summary": "India Today reported on the QS Asia University Rankings 2026, examining whether any Indian institution features among Asia's top 10 universities. Historically, Indian Institutes of Technology (IITs) have featured in the top tier of Asian rankings, with IIT Bombay and IIT Delhi among the highest-placed Indian institutions. The QS rankings are published by Quacquarelli Symonds and are based on academic reputation, employer reputation, faculty-to-student ratio, and research citations. India's higher education performance is benchmarked globally through such rankings under the National Education Policy 2020 goals.", "exam_angle": "University rankings, the National Education Policy 2020, and India's global higher education ambitions are relevant to GS Paper 2 (Education/Governance). QS, THE, and NIRF are the key ranking systems aspirants must know.", "gs_paper": "GS Paper 2 (Governance)", "key_facts": ["Ranking: QS Asia University Rankings 2026 (published by Quacquarelli Symonds)", "Top Indian institutions: IIT Bombay, IIT Delhi typically among highest-placed", "Rankings based on: Academic reputation, employer reputation, citations, faculty ratio", "India's domestic ranking system: NIRF (National Institutional Ranking Framework)"], "source": "India Today", "day": "2026-07-15", "day_label": "15 Jul"}, {"title": "Dara Singh (Graham Staines Murder Convict) May Be Released on Independence Day", "category": "polity", "category_name": "Polity & Governance", "summary": "Dara Singh, the main convict in the 1999 murder of Australian missionary Graham Staines and his two young sons in Odisha, may be released from prison around Independence Day (August 15), according to media reports. Dara Singh was sentenced to life imprisonment by the Supreme Court in 2011 after his death sentence was commuted. The Staines murder case was a landmark in debates around minority rights, communal violence, and judicial process in India. The potential release has reignited public discourse on remission of sentences in heinous crimes.", "exam_angle": "The Staines murder case is relevant to GS Paper 2 (Polity/Governance) topics on remission of sentences under Articles 72 and 161, minority rights, and the Supreme Court's commutation of death sentences.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Convict: Dara Singh, main accused in 1999 Graham Staines murder case", "Victim: Graham Staines and his two sons, burned alive in Keonjhar, Odisha", "Supreme Court commuted death sentence to life imprisonment in 2011", "Remission of sentences governed by Articles 72 (President) and 161 (Governor)"], "source": "The Times of India / India Today", "day": "2026-07-15", "day_label": "15 Jul"}, {"title": "India-US Defence Technology Ties: Aspirations Outpace Actual Delivery", "category": "defence", "category_name": "Defence & Security", "summary": "An analysis in The Hindu highlighted that despite ambitious frameworks such as the Initiative on Critical and Emerging Technology (iCET) and the Defence Industrial Cooperation Roadmap, actual technology transfer from the US to India remains limited. Key areas like jet engine co-production (GE F414 for Tejas Mk2), armed drones, and semiconductor supply chains are progressing slowly. The article noted structural impediments including US export control laws (ITAR/EAR), bureaucratic delays, and differences in industrial capability. India's push for 'Aatmanirbhar Bharat' in defence makes this gap particularly significant.", "exam_angle": "India-US defence cooperation, iCET, ITAR/EAR export controls, and Aatmanirbhar Bharat in defence are key GS Paper 2 (IR) and GS Paper 3 (Defence) topics.", "gs_paper": "GS Paper 3 (Defence)", "key_facts": ["Framework: Initiative on Critical and Emerging Technology (iCET), launched 2023", "Key project: GE F414 engine co-production for Tejas Mk2 fighter jet", "US export control laws (ITAR/EAR) remain a structural barrier", "India's defence self-reliance goal under Aatmanirbhar Bharat"], "source": "The Hindu", "day": "2026-07-15", "day_label": "15 Jul"}, {"title": "Iran Strikes UAE Oil Tankers in Strait of Hormuz; One Indian Sailor Killed, Several Injured", "category": "ir", "category_name": "International Relations", "summary": "Iranian missiles struck UAE-flagged oil tankers in the Strait of Hormuz, killing one Indian sailor and injuring six to eight others. India's Ministry of External Affairs summoned Iran's senior-most diplomat in New Delhi to protest the attack on Indian nationals aboard commercial vessels. The incident occurred amid an active US-Iran military conflict, with the US having launched multiple rounds of strikes on Iran. The attack on commercial shipping in a critical global waterway has sharply escalated geopolitical and economic tensions.", "exam_angle": "Tests knowledge of India's diplomatic protocol (summoning envoys), India's responsibility to protect its diaspora/sailors abroad, and the strategic importance of the Strait of Hormuz for India's energy security and trade.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["1 Indian sailor killed, 6–8 injured in Iranian missile strikes on UAE tankers in Hormuz", "MEA summoned Iran's senior-most diplomat; action taken by Ministry of External Affairs", "Strait of Hormuz: ~20% of global oil trade passes through it; Iran and Oman share jurisdiction", "Incident date: July 14, 2026"], "source": "The Hindu / NDTV", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "US Announces 20% Toll on Ships Using Strait of Hormuz; Trump Claims Control of Waterway", "category": "ir", "category_name": "International Relations", "summary": "US President Donald Trump announced a 20% fee (toll) on all cargo ships transiting the Strait of Hormuz, alongside a proposed blockade of Iran. Trump claimed the US would function as 'guardian' of the strait and should be reimbursed by nations benefiting from its security. Iran rejected the demand, calling it excessive. The move has significant implications for global oil trade, India's energy imports, and international maritime law under UNCLOS.", "exam_angle": "Relevant to international maritime law (UNCLOS — right of innocent passage through international straits), India's energy security (over 60% of India's crude oil imports transit Hormuz), and US-Iran geopolitics.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Trump proposed 20% toll on all cargo transiting Strait of Hormuz", "Strait of Hormuz: bordered by Iran and Oman; ~21 million barrels of oil/day pass through it", "UNCLOS guarantees 'transit passage' rights through international straits", "India imports ~60–65% of its crude oil from the Gulf; heavily exposed to Hormuz disruptions"], "source": "NDTV / The Hindu", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "UAE Plans New Port on East Coast to Bypass Strait of Hormuz", "category": "places", "category_name": "Places in News", "summary": "The UAE announced plans to build a new port on its east coast (facing the Gulf of Oman) to reduce dependence on the Strait of Hormuz amid escalating US-Iran conflict. The port would allow UAE oil exports to bypass the strait entirely. State oil company ADNOC also tweaked offshore oil pricing to support non-Hormuz supply routes. This is a significant strategic infrastructure response to the crisis.", "exam_angle": "Relevant to understanding alternative maritime routes, energy security strategy, and the geopolitical significance of the Strait of Hormuz for Gulf nations and global trade.", "gs_paper": "GS Paper 1 (Geography)", "key_facts": ["UAE planning new east coast port to bypass Strait of Hormuz", "Port would face the Gulf of Oman, allowing direct access to Indian Ocean", "UAE's ADNOC adjusting pricing to support alternate supply routes", "Existing UAE bypass: Habshan–Fujairah pipeline (capacity ~1.5 mb/d)"], "source": "The Times of India / NDTV", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "India Launches UNSC Campaign for 2028–29 Term; Jaishankar Unveils 'SHANTI' Vision", "category": "ir", "category_name": "International Relations", "summary": "External Affairs Minister S. Jaishankar formally launched India's campaign for a non-permanent seat on the UN Security Council for the 2028–29 term, unveiling the 'SHANTI' vision as India's guiding framework. SHANTI stands for India's priorities at the UNSC — encompassing maritime security, seafarer safety, counter-terrorism financing, and a more inclusive global order. Jaishankar also met UN Secretary-General to discuss Middle East and Ukraine crises. India simultaneously pushed for a permanent UNSC seat as part of broader UN reform.", "exam_angle": "Directly relevant to India's foreign policy priorities, UNSC reform, India's bid for permanent membership, and current multilateral diplomacy. 'SHANTI' vision is a high-probability exam fact.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India campaigning for UNSC non-permanent seat for 2028–29 term", "EAM Jaishankar unveiled 'SHANTI' vision as India's UNSC agenda", "SHANTI focuses on: maritime security, seafarer safety, terror financing crackdown", "India is pushing for permanent UNSC membership as part of UN Security Council reform"], "source": "The Times of India / News18", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "NIA Court Issues Non-Bailable Warrant Against LeT Founder Hafiz Saeed in Pahalgam Terror Attack Case", "category": "polity", "category_name": "Polity & Governance", "summary": "A National Investigation Agency (NIA) court issued a non-bailable warrant (NBW) against Lashkar-e-Taiba (LeT) founder Hafiz Saeed in connection with the Pahalgam terror attack. Saeed, already convicted in Pakistan on terror financing charges and designated a global terrorist by the UN, is now formally accused in the Pahalgam case. The NIA has jurisdiction over cross-border terrorism cases under the NIA Act, 2008. This marks a significant legal step linking Pakistan-based terror outfits to the attack.", "exam_angle": "Tests knowledge of NIA's jurisdiction, NBW provisions under CrPC/BNSS, India's counter-terrorism legal framework, and Pakistan-sponsored terrorism — all key polity/internal security themes.", "gs_paper": "GS Paper 3 (Internal Security)", "key_facts": ["NIA court issued NBW against Hafiz Saeed for Pahalgam terror attack", "Hafiz Saeed: founder of Lashkar-e-Taiba (LeT); UN-designated global terrorist", "NIA operates under NIA Act, 2008; has jurisdiction over terrorism cases", "Pahalgam attack: occurred in Jammu & Kashmir; investigated by NIA"], "source": "The Times of India / The Hindu", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Supreme Court Questions Misuse of POCSO Act in Teen Relationships", "category": "polity", "category_name": "Polity & Governance", "summary": "The Supreme Court of India raised concerns about the misuse of the Protection of Children from Sexual Offences (POCSO) Act, 2012, in cases involving consensual relationships between teenagers. The Court noted that POCSO, designed to protect children from sexual abuse, was being invoked in cases where both parties were minors engaged in consensual relationships, leading to the criminalisation of normal adolescent behaviour. The observation has implications for judicial interpretation and potential legislative review of the Act.", "exam_angle": "Relevant to GS Paper 2 (Polity/Governance) — POCSO Act provisions, judicial interpretation, child rights, and the balance between child protection and individual liberty. SC observations often precede policy changes.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["POCSO Act, 2012: protects children (under 18) from sexual offences", "SC raised concern about POCSO being misused in consensual teen relationships", "POCSO is a strict liability statute — consent is not a defence for accused", "Issue touches on Articles 14, 19, 21 of the Constitution"], "source": "The Hindu", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "India's Goods Trade Deficit Widens to 5-Month High Amid Hormuz Disruptions", "category": "economy", "category_name": "Economy & Banking", "summary": "India's merchandise trade deficit hit a five-month high as imports surged, partly due to disruptions in the Strait of Hormuz driving up crude oil import costs. Weak exports also contributed to the widening deficit. India's imports from China soared to $80 billion in the first half of 2026, with exports to China up 37%. The US-Iran conflict is simultaneously raising inflation risks for India through elevated oil prices and potential El Niño impacts on food inflation.", "exam_angle": "Key for GS Paper 3 (Economy) — India's trade balance, current account deficit, crude oil import dependence, China trade asymmetry, and imported inflation are all standard exam themes.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["India's trade deficit at 5-month high; imports surged due to Hormuz-linked oil price rise", "India's imports from China: $80 billion in H1 2026; India's exports to China up 37%", "Inflation risks mounting: US-Iran tensions + El Niño = dual supply-side shock", "India imports ~85% of its crude oil requirement"], "source": "Reuters / The Times of India / Bloomberg", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "India–US Trade Deal: Framework Agreed; Competitive Advantage Clauses Still Under Discussion", "category": "ir", "category_name": "International Relations", "summary": "India and the United States agreed on a broad framework for a bilateral trade deal, but negotiations on 'competitive advantage' aspects — including tariff concessions and market access — remain ongoing. New Delhi stated it is holding out for better terms in areas such as agriculture, digital trade, and intellectual property. Reports indicate India is in a stronger negotiating position ('emboldened') given US interest in diversifying away from China. The deal framework was described as a significant step in India-US economic engagement.", "exam_angle": "India-US trade relations are a recurring GS Paper 2 (IR) and GS Paper 3 (Economy) topic — relevant to BTA, WTO commitments, and India's trade strategy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India-US trade deal framework agreed as of July 2026", "Contentious issues: competitive advantage clauses, tariff concessions, digital trade", "India is US's 9th largest trading partner; bilateral trade ~$190 billion", "India holding out on agriculture market access and IPR provisions"], "source": "Reuters / Scroll.in / The Indian Express", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Government Receives Revised Bids for IDBI Bank Stake Sale from Fairfax, Emirates NBD", "category": "economy", "category_name": "Economy & Banking", "summary": "The Indian government received revised financial bids for its strategic disinvestment of IDBI Bank from two shortlisted bidders — Canada's Fairfax Financial Holdings and UAE-based Emirates NBD. The government and Life Insurance Corporation (LIC) together hold over 94% stake in IDBI Bank and plan to sell a combined ~61% stake. The IDBI Bank privatisation is one of the flagship disinvestment initiatives under the government's asset monetisation and privatisation agenda.", "exam_angle": "IDBI Bank privatisation is a standard exam topic under GS Paper 3 (Economy) — disinvestment policy, banking sector reforms, and the role of LIC as a major shareholder.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Revised bids received from Fairfax (Canada) and Emirates NBD (UAE) for IDBI Bank stake", "Government + LIC hold ~94% in IDBI Bank; plan to sell ~61% stake", "IDBI Bank privatisation: part of Union Budget disinvestment targets", "IDBI Bank was categorised as 'private sector bank' by RBI after LIC acquired majority stake in 2019"], "source": "Reuters", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Karnataka CM Announces India's First Government-Driven AI University", "category": "scitech", "category_name": "Science & Technology", "summary": "Karnataka Chief Minister Siddaramaiah announced that Karnataka would establish India's first government-driven Artificial Intelligence (AI) university. The institution aims to position Karnataka — already home to Bengaluru, India's tech capital — as a leader in AI education, research, and innovation. The announcement aligns with India's National Strategy for Artificial Intelligence (NSAI) and the IndiaAI Mission launched by the Union government.", "exam_angle": "Relevant to GS Paper 3 (Sci-Tech) — India's AI policy, IndiaAI Mission, skill development, and state-level tech governance initiatives.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Karnataka to establish India's first government-driven AI university", "Announced by CM Siddaramaiah", "India's National Strategy for AI (NSAI) released by NITI Aayog in 2018", "IndiaAI Mission: Union government initiative with Rs 10,372 crore outlay (2024)"], "source": "The Hindu / The Economic Times", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Sonam Wangchuk on Day 16 of Hunger Strike at CJP Protest; Loses 8.2 kg", "category": "polity", "category_name": "Polity & Governance", "summary": "Climate activist and engineer Sonam Wangchuk continued his hunger strike for the 16th consecutive day at an ongoing protest related to demands for constitutional protections for Ladakh. Wangchuk has lost 8.2 kg and demands the resignation of Union Education Minister Dharmendra Pradhan. AAP chief Arvind Kejriwal announced he would meet Wangchuk on July 16, 2026. The protest is linked to demands for Sixth Schedule protections and statehood for Ladakh.", "exam_angle": "Relevant to GS Paper 2 (Polity) — Sixth Schedule of the Constitution, Ladakh's status as a Union Territory without a legislature, tribal rights, and civil society activism.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Sonam Wangchuk: Ladakh-based activist-engineer; hunger strike for 16 days as of July 14, 2026", "Key demands: Sixth Schedule protection for Ladakh, full statehood for Ladakh", "Ladakh became a Union Territory (without legislature) on October 31, 2019 under J&K Reorganisation Act", "Sixth Schedule: provides autonomy to tribal areas in NE India; Ladakh seeks inclusion"], "source": "BBC / The Hindu", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Oil Prices Surge to One-Month High; Indian Markets Fall as US-Iran Conflict Escalates", "category": "economy", "category_name": "Economy & Banking", "summary": "Crude oil prices surged to a one-month high as the US-Iran conflict escalated, with the Strait of Hormuz crisis disrupting global energy markets. India's Sensex fell over 553 points in early trade as rising oil prices dented market sentiment. Indian airlines, particularly newer carriers, began seeking emergency funding as aviation turbine fuel (ATF) costs surged. The dual risk of higher crude oil prices and weakening rupee poses a significant macroeconomic challenge for India.", "exam_angle": "Classic GS Paper 3 (Economy) theme — impact of crude oil price shocks on India's fiscal deficit, CAD, inflation, and currency. Also tests understanding of India's energy import dependence.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Crude oil hit one-month high; Brent crude surged amid Hormuz crisis", "Sensex fell 553 points on July 14, 2026 due to oil price spike", "India's oil import bill ~$150 billion/year; every $10/barrel rise = ~$15 billion additional outgo", "ATF comprises ~35–40% of airline operating costs in India"], "source": "The Hindu / The Times of India / Moneycontrol", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "Vietnam Boat Tragedy: Bodies of 15 Indians Return to Mumbai", "category": "ir", "category_name": "International Relations", "summary": "The mortal remains of 15 Indians killed in a boat accident in Vietnam were repatriated and arrived in Mumbai. The victims, including at least one Andhra Pradesh resident for whom it was his maiden air travel, were among a group of Indian tourists caught in the tragedy. India's consular officials coordinated the repatriation. The incident highlights risks faced by Indian tourists abroad and the role of Indian diplomatic missions in consular assistance.", "exam_angle": "Relevant to India's consular services, diaspora protection, and the role of MEA's consular wing — important for GS Paper 2 (IR) and governance questions on Indian diaspora welfare.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["15 Indians killed in Vietnam boat accident; bodies repatriated to Mumbai", "At least one victim from Andhra Pradesh", "Consular assistance provided by Indian diplomatic mission in Vietnam", "MEA's consular wing oversees emergency assistance to Indians abroad"], "source": "The Times of India / Deccan Herald", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "India's Imports from China Hit $80 Billion in H1 2026; Trade Asymmetry Grows", "category": "economy", "category_name": "Economy & Banking", "summary": "India's imports from China soared to $80 billion in the first half of 2026, while India's exports to China rose 37% in the same period. Despite the export growth, the bilateral trade deficit with China remains structurally large. India continues to import significant volumes of electronics, solar panels, active pharmaceutical ingredients (APIs), and industrial machinery from China. The asymmetry is a persistent concern for India's manufacturing competitiveness and supply chain security.", "exam_angle": "India-China trade deficit is a standard GS Paper 3 (Economy) topic — linked to PLI schemes, Atmanirbhar Bharat, API dependence, and import substitution policy.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["India's imports from China: $80 billion in H1 2026", "India's exports to China: up 37% in H1 2026", "India-China trade deficit: one of India's largest bilateral deficits", "Key imports from China: electronics, solar cells, APIs, machinery"], "source": "The Hindu", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "IIT Bhubaneswar Researchers Develop Technology for Faster Computers", "category": "scitech", "category_name": "Science & Technology", "summary": "Researchers at IIT Bhubaneswar have developed a new semiconductor technology aimed at building significantly faster computers. The innovation focuses on improving transistor performance, potentially overcoming limitations of traditional silicon-based chips. The development is significant in the context of India's push for semiconductor self-sufficiency under the India Semiconductor Mission and the Semicon India Programme.", "exam_angle": "Relevant to GS Paper 3 (Sci-Tech) — semiconductor technology, India Semiconductor Mission, and India's push for self-reliance in critical technology.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["IIT Bhubaneswar developed new technology to build faster computers", "Focus: improving semiconductor/transistor performance beyond silicon limitations", "India Semiconductor Mission: Rs 76,000 crore incentive scheme for semiconductor manufacturing", "Semicon India Programme: launched 2021 to develop domestic chip ecosystem"], "source": "The New Indian Express", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "India Women's Cricket Team Wins Historic Test at Lord's", "category": "persons", "category_name": "Persons & Awards in News", "summary": "The Indian women's cricket team achieved a landmark victory in a Test match at Lord's Cricket Ground, London — a historically significant result for women's cricket in India. Captain Harmanpreet Kaur reflected on the milestone win, describing it as an 'ode to pioneering women cricketers.' The victory is being hailed as a defining moment in the growth of women's cricket in India and comes as BCCI has been increasing investment in the women's game.", "exam_angle": "Relevant for GS Paper 1 (Society) or current affairs on women's empowerment in sports; Harmanpreet Kaur is a 'Person in News.' Lord's is a culturally significant venue (the 'Home of Cricket').", "gs_paper": "GS Paper 1 (Culture)", "key_facts": ["India Women's cricket team won a Test match at Lord's, London", "Captain: Harmanpreet Kaur", "Lord's Cricket Ground: located in London; managed by Marylebone Cricket Club (MCC)", "BCCI launched Women's IPL (WPL) in 2023 to boost women's cricket"], "source": "BBC / Deccan Herald", "day": "2026-07-14", "day_label": "14 Jul"}, {"title": "India's Theatre Command Plan Nears Approval After Two Decades", "category": "defence", "category_name": "Defence & Security", "summary": "Chief of Defence Staff General Anil Chauhan (referred to as CDS Subramani in some reports) is set to seek formal approval for India's theatre commands from Defence Minister Rajnath Singh, marking a landmark moment in military reform. Theatrisation refers to the integration of Army, Navy, and Air Force assets under unified geographic commands for synergised operations. The plan has been in deliberation for over 20 years and is India's most significant military restructuring since independence. The approval would lead to the creation of joint theatre commands, replacing the current single-service command structure.", "exam_angle": "Theatrisation is a core topic under GS Paper 3 (Internal Security & Defence); questions frequently appear on the role of CDS, jointness in armed forces, and defence reforms post-Kargil Review Committee.", "gs_paper": "GS Paper 3 (Defence)", "key_facts": ["Theatre commands integrate Army, Navy, and Air Force under unified geographic commands", "Approval to be sought from Defence Minister Rajnath Singh", "CDS is the nodal authority for promoting jointness and theatrisation", "Reform has been under discussion for over 20 years; recommended post-Kargil Review Committee (1999)"], "source": "NDTV / Hindustan Times", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "India-Australia Administrative Arrangements for Uranium Supplies Signed", "category": "ir", "category_name": "International Relations", "summary": "During PM Narendra Modi's visit to Australia, both countries signed administrative arrangements for uranium supplies to India, strengthening the civil nuclear cooperation framework established under the 2014 India-Australia Civil Nuclear Cooperation Agreement. PM Modi gifted Australian PM Anthony Albanese premium coffee and a Colonial Cousins vinyl album. The uranium supply arrangements are significant for India's nuclear energy programme and energy security goals.", "exam_angle": "India's civil nuclear agreements and uranium supply arrangements are important for GS Paper 2 (IR) — connects to India's nuclear energy policy, NSG waiver (2008), and bilateral energy diplomacy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India-Australia Civil Nuclear Cooperation Agreement originally signed in 2014", "Administrative arrangements for uranium supplies formalised during PM Modi's Australia visit", "Australia is among the world's largest uranium producers", "India requires uranium imports for its civilian nuclear power programme"], "source": "NDTV / The Hindu", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Maharashtra's Ladki Bahin Scheme: 92 Lakh Beneficiaries Removed After Verification; CAG Flags Rs 3,541 Crore Excess Spend", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "Maharashtra's Ladki Bahin Yojana, a scheme providing monthly financial assistance to women, saw approximately 92 lakh (nearly 4 in 10) beneficiaries dropped following a verification drive. The Comptroller and Auditor General (CAG) flagged Rs 3,541 crore in excess expenditure and budgetary lapses in the scheme's implementation. The scheme had been a major electoral promise before the 2024 Maharashtra Assembly elections. The large-scale removal of beneficiaries raises questions about initial enrolment processes and fiscal management.", "exam_angle": "Connects to GS Paper 2 (Governance) — Direct Benefit Transfer, welfare scheme implementation, CAG's role as constitutional auditor (Article 148), and fiscal federalism issues.", "gs_paper": "GS Paper 2 (Governance)", "key_facts": ["Ladki Bahin Yojana: monthly cash transfer scheme for women in Maharashtra", "92 lakh beneficiaries (nearly 40%) removed after verification", "CAG flagged Rs 3,541 crore excess expenditure and budgetary lapses", "CAG is a constitutional body under Article 148 of the Constitution"], "source": "Moneycontrol / The Hindu", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "India Declares One-Day National Mourning for Former Qatar Emir Sheikh Hamad Al Thani", "category": "ir", "category_name": "International Relations", "summary": "India declared one day of national mourning following the death of former Emir of Qatar, Sheikh Hamad bin Khalifa Al Thani. Qatar is a strategically important partner for India, being a major source of LNG imports and home to a large Indian diaspora. The gesture reflects the depth of India-Qatar bilateral ties. Sheikh Hamad had ruled Qatar from 1995 to 2013 before abdicating in favour of his son, Sheikh Tamim bin Hamad Al Thani.", "exam_angle": "India-Qatar relations are relevant for GS Paper 2 (IR) — energy diplomacy, diaspora, Gulf Cooperation Council (GCC) engagement, and India's LNG import dependency.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Former Emir Sheikh Hamad bin Khalifa Al Thani ruled Qatar from 1995–2013", "India declared one day of national mourning", "Qatar is a major supplier of LNG to India", "Large Indian diaspora resides in Qatar; bilateral ties include energy, trade, and labour"], "source": "NDTV", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "US-Iran Military Strikes Escalate; Oil Prices Jump 4%, Rupee Slips 39 Paise", "category": "economy", "category_name": "Economy & Banking", "summary": "The United States launched a new wave of airstrikes against Iran after Tehran declared diplomacy had proven 'futile' following the death of Supreme Leader Khamenei. The escalation pushed global oil prices up by 4%, triggering concerns about the Strait of Hormuz and energy supply disruptions. Consequently, the Indian rupee slipped 39 paise against the US dollar, reflecting pressure on India's current account given its heavy oil import dependency. India's trade deficit also widened as Hormuz uncertainty clouded the outlook.", "exam_angle": "Connects to GS Paper 3 (Economy) — oil price impact on India's macroeconomics, current account deficit, exchange rate management by RBI, and geopolitical risk to energy security.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["US launched new airstrikes against Iran; Tehran declared diplomacy 'futile'", "Global oil prices rose approximately 4%", "Indian rupee fell 39 paise against US dollar", "Strait of Hormuz: critical chokepoint through which ~20% of global oil trade passes"], "source": "The Times of India / Bloomberg / The Guardian", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "India-US Trade Deal Talks: India Refuses Rush, Holds Firm on Agriculture", "category": "ir", "category_name": "International Relations", "summary": "India's Trade Secretary stated that India is progressing on a trade deal with the US but sees no major challenges, while simultaneously reports indicated India is refusing a rushed agreement and will not cede ground on agriculture. India is seeking tariff advantages before finalising any deal. The negotiations come amid the US applying reciprocal tariffs on Indian goods, and India prioritising national interests in sectors like dairy and agriculture.", "exam_angle": "India-US bilateral trade negotiations are key for GS Paper 2 (IR) and GS Paper 3 (Economy); connects to WTO obligations, agriculture subsidies, and India's trade policy stance.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India's Trade Secretary confirmed progress on India-US trade deal", "India refusing to cede ground on agriculture sector in trade negotiations", "India seeking tariff advantages before signing", "Context: US imposed reciprocal tariffs; India is among the top US trading partners"], "source": "Reuters / Times of India / Firstpost", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Bharat Tex 2026: India to Host World's Largest Global Textiles Expo", "category": "economy", "category_name": "Economy & Banking", "summary": "India is preparing to host Bharat Tex 2026, described as the world's largest global textiles expo. The event is organised to showcase India's textile sector, attract global buyers and investors, and reinforce India's position as a global textile hub. The PIB announcement highlights the government's focus on promoting the textile industry as a key driver of exports and employment. India is among the world's largest textile and apparel exporters.", "exam_angle": "Relevant for GS Paper 3 (Economy) — India's textile industry, export promotion, Make in India, and schemes like PM MITRA (Mega Integrated Textile Region and Apparel) Parks.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Bharat Tex 2026: billed as the world's largest global textiles expo", "Organised by India to showcase textile sector capabilities", "India is among the world's top 5 textile and apparel exporters", "Connects to PM MITRA scheme and National Textile Policy"], "source": "PIB", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Supreme Court Releases Draft Report on Use of Artificial Intelligence in Courtrooms", "category": "polity", "category_name": "Polity & Governance", "summary": "The Supreme Court of India released a draft report on the use of Artificial Intelligence (AI) in courtrooms, examining how AI tools can assist in judicial processes including case management, legal research, and transcription. The report is part of the judiciary's effort to modernise court infrastructure and reduce pendency. It raises important questions about data privacy, algorithmic bias, and accountability in judicial decision-making. The Supreme Court has previously launched the SUPACE (Supreme Court Portal for Assistance in Court's Efficiency) AI tool.", "exam_angle": "Relevant for GS Paper 2 (Polity/Governance) — judicial reforms, technology in governance, and GS Paper 3 (Sci-Tech) — AI regulation and ethics; SUPACE is a frequently asked fact.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Supreme Court released draft report on AI use in courtrooms", "SUPACE: AI tool previously launched by Supreme Court for judicial efficiency", "Report addresses data privacy, algorithmic bias, and judicial accountability", "Judiciary aims to use AI to reduce case pendency (over 5 crore cases pending in India)"], "source": "NDTV", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Karnataka Governor Suspends KPSC Chairman Over Illegal Appointments of Daughters", "category": "polity", "category_name": "Polity & Governance", "summary": "The Governor of Karnataka suspended the Karnataka Public Service Commission (KPSC) Chairman following a controversy over the illegal appointment of his daughters. The KPSC is a constitutional body responsible for recruitment to state civil services under Article 315 of the Constitution. The Governor exercised powers to suspend the chairman pending inquiry into the alleged nepotism and irregularities in appointments.", "exam_angle": "Directly relevant to GS Paper 2 (Polity) — constitutional bodies, role of Public Service Commissions (Article 315–323), Governor's powers, and issues of accountability in recruitment bodies.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["KPSC: Karnataka Public Service Commission, constituted under Article 315 of the Constitution", "Chairman suspended by Karnataka Governor for illegally appointing his daughters", "PSC members can be removed only by the President/Governor after Supreme Court/High Court inquiry (Article 317)", "KPSC conducts recruitment to Group A & B state civil services"], "source": "Hindustan Times", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Two Pakistanis Arrested in Karnataka's Chikkaballapur for Obtaining Voter IDs", "category": "polity", "category_name": "Polity & Governance", "summary": "Two Pakistani nationals were arrested in Chikkaballapur, Karnataka, for allegedly obtaining Indian Voter Identity Cards fraudulently. The case raises serious concerns about illegal infiltration and document fraud, and highlights vulnerabilities in the electoral roll management process. The Election Commission of India is responsible for maintaining electoral rolls, and obtaining a Voter ID by a foreign national is an offence under the Representation of the People Act, 1950.", "exam_angle": "Relevant to GS Paper 2 (Polity) — electoral integrity, Representation of the People Act, and internal security concerns; also connects to Foreigners Act and citizenship laws.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Two Pakistani nationals arrested in Chikkaballapur, Karnataka", "Charge: fraudulently obtaining Indian Voter Identity Cards", "Offence under Representation of the People Act, 1950", "Election Commission of India is the constitutional body for electoral roll management (Article 324)"], "source": "News18", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "BrahMos Missile Completes 25 Years: India's Supersonic Cruise Missile Technology and Future Plans", "category": "defence", "category_name": "Defence & Security", "summary": "BrahMos, India's supersonic cruise missile developed jointly by India (DRDO) and Russia (NPO Mashinostroyeniya), completes 25 years of its development journey. BrahMos is the world's fastest operational supersonic cruise missile, capable of speeds up to Mach 2.8–3.0. India has been expanding BrahMos exports (Philippines being the first buyer) and developing an extended-range (450 km+) and hypersonic version (BrahMos-II/BrahMos-NG). The missile is deployed across all three services — Army, Navy, and Air Force.", "exam_angle": "BrahMos is a perennial UPSC favourite under GS Paper 3 (Sci-Tech/Defence) — covers DRDO, India-Russia defence cooperation, indigenisation, and export diplomacy.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["BrahMos: joint venture between DRDO (India) and NPO Mashinostroyeniya (Russia)", "World's fastest operational supersonic cruise missile — speed ~Mach 2.8–3.0", "First export customer: Philippines (2022 contract)", "BrahMos-NG (Next Generation) and BrahMos-II (hypersonic) under development"], "source": "The Times of India", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "MeitY Secretary Calls for Resilient Software and Hardware Systems to Counter Cyber Threats", "category": "scitech", "category_name": "Science & Technology", "summary": "The Secretary of the Ministry of Electronics and Information Technology (MeitY) emphasised the need for India to build resilient domestic software and hardware systems capable of withstanding growing cyber threats. The statement was made in the context of rising geopolitical cyber risks and India's push for technological self-reliance. The remarks align with India's National Cyber Security Policy and the Semicon India programme for domestic semiconductor manufacturing.", "exam_angle": "Relevant for GS Paper 3 (Sci-Tech and Internal Security) — cyber security policy, MeitY's role, India Semiconductor Mission, and digital sovereignty.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["MeitY: Ministry of Electronics and Information Technology oversees India's digital and cyber policy", "Call for indigenous, resilient software and hardware to counter cyber threats", "Connects to India Semiconductor Mission (ISM) and Semicon India programme", "National Cyber Security Policy 2013 is being updated; CERT-In is the nodal agency for cyber incidents"], "source": "The Economic Times", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Vietnam Boat Tragedy: Mortal Remains of 15 Indian Tourists Repatriated to India", "category": "ir", "category_name": "International Relations", "summary": "The mortal remains of 15 Indian tourists killed in a speedboat accident near Phu Quoc island in Vietnam were repatriated to India, with bodies reaching Mumbai and Hyderabad. The tragedy occurred when a speedboat capsized, killing the Indian tourists. Indian consular officials coordinated the repatriation process. The incident raises questions about tourist safety regulations in Vietnam and India's consular response mechanisms.", "exam_angle": "Relevant for GS Paper 2 (IR) — India's consular services, diaspora protection, Ministry of External Affairs' role, and bilateral India-Vietnam relations.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["15 Indian tourists killed in speedboat accident near Phu Quoc island, Vietnam", "Mortal remains repatriated to India (Mumbai and Hyderabad)", "Indian consular officials coordinated repatriation", "India-Vietnam: Comprehensive Strategic Partnership (upgraded in 2016)"], "source": "The Times of India / India Today / The Hindu", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Europe Records Over 10,000 Excess Deaths During June 2026 Heatwave", "category": "environment", "category_name": "Environment & Ecology", "summary": "A report recorded over 10,000 excess deaths across Europe during the June 2026 heatwave, highlighting the growing health impact of climate change-driven extreme heat events. Excess deaths refer to deaths above the statistically expected baseline during the same period in normal years. The event underscores the urgency of heat action plans and adaptation strategies. The World Meteorological Organization (WMO) has repeatedly flagged Europe as one of the fastest-warming continents.", "exam_angle": "Relevant for GS Paper 3 (Environment) and GS Paper 1 (Geography) — climate change impacts, heat action plans, WMO reports, and urban heat island effect.", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["Over 10,000 excess deaths recorded in Europe during June 2026 heatwave", "'Excess deaths': deaths above statistically expected baseline", "WMO identifies Europe as one of the fastest-warming continents", "India has National Heat Action Plans (implemented by NDMA) as a parallel context"], "source": "NDTV", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Commerce Ministry to Lead Business Delegation to Spain, Belgium and Finland for Trade and Technology Ties", "category": "ir", "category_name": "International Relations", "summary": "The Union Minister of Commerce and Industry is set to lead an Indian business delegation to Spain, Belgium, and Finland to strengthen trade, investment, and technology linkages. The visit is part of India's broader engagement with European Union member states ahead of the India-EU Free Trade Agreement (FTA) negotiations. Belgium is home to major EU institutions, while Finland and Spain are significant trade and technology partners.", "exam_angle": "Relevant for GS Paper 2 (IR) — India-EU relations, FTA negotiations, and trade diplomacy; Belgium's importance as EU institutional hub is a useful fact.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Commerce Minister to lead delegation to Spain, Belgium, and Finland", "Objective: boost trade, investment, and technology ties", "Belgium hosts key EU institutions (European Commission, Council)", "India-EU FTA negotiations (Broad-based Trade and Investment Agreement) are ongoing"], "source": "Business Standard", "day": "2026-07-13", "day_label": "13 Jul"}, {"title": "Sonam Wangchuk's Hunger Strike: Citizens for Justice and Peace Issues Open Letter", "category": "polity", "category_name": "Polity & Governance", "summary": "Citizens for Justice and Peace (CJP) issued an open letter in response to activist Sonam Wangchuk's ongoing hunger strike, demanding statehood and constitutional safeguards (Sixth Schedule protections) for Ladakh. Wangchuk, a Magsaysay Award-winning engineer and activist, has been demanding that Ladakh be granted full statehood or included in the Sixth Schedule of the Constitution to protect tribal land and resources. Ladakh has been a Union Territory (without legislature) since October 31, 2019, following the reorganisation of Jammu & Kashmir.", "exam_angle": "Directly relevant to GS Paper 2 (Polity) — Sixth Schedule, constitutional status of Ladakh, Article 370 reorganisation, and tribal rights under Fifth and Sixth Schedules.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Sonam Wangchuk: Magsaysay Award-winning activist from Ladakh", "Demands: statehood for Ladakh OR inclusion under Sixth Schedule of the Constitution", "Sixth Schedule: protects tribal autonomy in northeastern states; covers Assam, Meghalaya, Tripura, Mizoram", "Ladakh became a UT without legislature on October 31, 2019 (J&K Reorganisation Act, 2019)"], "source": "The Indian Express", "day": "2026-07-13", "day_label": "13 Jul"}], "categories": [{"id": "polity", "name": "Polity & Governance"}, {"id": "economy", "name": "Economy & Banking"}, {"id": "ir", "name": "International Relations"}, {"id": "environment", "name": "Environment & Ecology"}, {"id": "scitech", "name": "Science & Technology"}, {"id": "schemes", "name": "Govt Schemes & Policies"}, {"id": "defence", "name": "Defence & Security"}, {"id": "reports", "name": "Reports & Indices"}, {"id": "persons", "name": "Persons & Awards in News"}, {"id": "places", "name": "Places in News"}]};